-- Lote 02 do catálogo de talentos SRD: traduções revisadas.
-- Não altera engine_status: tradução não comprova integração funcional.
begin;
update public.srd_feats set nome_pt='Acrobático', descricao_pt='Benefício: Você recebe +2 de bônus em todos os testes de Saltar e Acrobacia.' where id='srd35_feat_acrobatic';
update public.srd_feats set nome_pt='Ágil', descricao_pt='Benefício: Você recebe +2 de bônus em todos os testes de Equilíbrio e Arte da Fuga.' where id='srd35_feat_agile';
update public.srd_feats set nome_pt='Prontidão', descricao_pt='Benefício: Você recebe +2 de bônus em todos os testes de Ouvir e Observar.\n\nEspecial: O mestre de um familiar recebe o benefício do talento Prontidão sempre que o familiar estiver ao alcance de seu braço.' where id='srd35_feat_alertness';
update public.srd_feats set nome_pt='Afinidade com Animais', descricao_pt='Benefício: Você recebe +2 de bônus em todos os testes de Adestrar Animais e Cavalgar.' where id='srd35_feat_animal_affinity';
update public.srd_feats set nome_pt='Proficiência com Armadura (Pesada)', descricao_pt='Pré-requisitos: Proficiência com Armadura (Leve) e Proficiência com Armadura (Média).\n\nBenefício: Consulte Proficiência com Armadura (Leve).\n\nNormal: Consulte Proficiência com Armadura (Leve).\n\nEspecial: Guerreiros, paladinos e clérigos recebem automaticamente Proficiência com Armadura (Pesada) como talento adicional. Eles não precisam escolhê-lo.' where id='srd35_feat_armor_proficiency_heavy';
update public.srd_feats set nome_pt='Proficiência com Armadura (Leve)', descricao_pt='Benefício: Quando você usa um tipo de armadura com a qual é proficiente, a penalidade de armadura se aplica apenas aos testes de Equilíbrio, Escalar, Arte da Fuga, Esconder-se, Saltar, Furtividade, Prestidigitação e Acrobacia.\n\nNormal: Um personagem que usa uma armadura com a qual não é proficiente aplica a penalidade de armadura às jogadas de ataque e a todos os testes de perícia que envolvam movimento, incluindo Cavalgar.\n\nEspecial: Todos os personagens, exceto magos, feiticeiros e monges, recebem automaticamente Proficiência com Armadura (Leve) como talento adicional. Eles não precisam escolhê-lo.' where id='srd35_feat_armor_proficiency_light';
update public.srd_feats set nome_pt='Proficiência com Armadura (Média)', descricao_pt='Pré-requisito: Proficiência com Armadura (Leve).\n\nBenefício: Consulte Proficiência com Armadura (Leve).\n\nNormal: Consulte Proficiência com Armadura (Leve).\n\nEspecial: Guerreiros, bárbaros, paladinos, clérigos, druidas e bardos recebem automaticamente Proficiência com Armadura (Média) como talento adicional. Eles não precisam escolhê-lo.' where id='srd35_feat_armor_proficiency_medium';
update public.srd_feats set nome_pt='Atlético', descricao_pt='Benefício: Você recebe +2 de bônus em todos os testes de Escalar e Natação.' where id='srd35_feat_athletic';
update public.srd_feats set nome_pt='Aprimorar Invocação', descricao_pt='Pré-requisito: Foco em Magia (conjuração).\n\nBenefício: Cada criatura que você conjurar com qualquer magia de invocação recebe +4 de bônus de aprimoramento em Força e Constituição durante toda a duração da magia que a invocou.' where id='srd35_feat_augment_summoning';
update public.srd_feats set nome_pt='Combater às Cegas', descricao_pt='Benefício: Em combate corpo a corpo, sempre que você errar um ataque devido à chance de falha por ocultação, pode repetir uma vez a jogada percentual dessa chance para verificar se realmente acertou.\n\nUm atacante invisível não recebe vantagens relacionadas a atingir você em combate corpo a corpo. Isto é, você não perde seu bônus de Destreza na Classe de Armadura, e o atacante não recebe o bônus habitual de +2 por estar invisível. Os bônus do atacante invisível ainda se aplicam a ataques à distância.\n\nVocê sofre apenas metade da penalidade habitual de deslocamento por não conseguir enxergar. Escuridão e visibilidade ruim em geral reduzem seu deslocamento para três quartos do normal, em vez de metade.\n\nNormal: Os modificadores normais de jogada de ataque para atacantes invisíveis que tentam atingi-lo são aplicados, e você perde seu bônus de Destreza na CA. A redução de deslocamento por escuridão e visibilidade ruim também se aplica.\n\nEspecial: O talento Combater às Cegas não oferece benefício contra um personagem afetado pela magia Piscar.\n\nUm guerreiro pode escolher Combater às Cegas como um de seus talentos adicionais de guerreiro.' where id='srd35_feat_blind_fight';
update public.srd_feats set nome_pt='Criar Poção', descricao_pt='Pré-requisito: Nível de conjurador 3º.\n\nBenefício: Você pode criar uma poção de qualquer magia de 3º nível ou inferior que conheça e que tenha como alvo uma ou mais criaturas. Preparar uma poção leva um dia. Ao criá-la, você define o nível de conjurador, que deve ser suficiente para conjurar a magia em questão e não pode ser superior ao seu próprio nível. O preço-base de uma poção é o nível da magia × o nível de conjurador × 50 PO. Para preparar uma poção, você deve gastar XP equivalente a 1/25 desse preço-base e utilizar matérias-primas que custem metade desse preço.\n\nAo criar a poção, você faz todas as escolhas que normalmente faria ao conjurar a magia. Quem beber a poção será o alvo da magia.\n\nQualquer poção que armazene uma magia com componente material caro ou custo em XP também incorpora um custo proporcional. Além dos custos calculados a partir do preço-base, você deve fornecer o componente material ou pagar o custo em XP ao criar a poção.' where id='srd35_feat_brew_potion';
commit;